DROP POLICY IF EXISTS clinical_prescription_scope ON public.prescriptions;
CREATE POLICY clinical_prescription_scope ON public.prescriptions AS RESTRICTIVE FOR ALL TO authenticated USING(patient_id=auth.uid() OR public.can_access_patient(patient_id)) WITH CHECK(public.can_access_patient(patient_id));
DROP POLICY IF EXISTS clinical_audit_scope ON public.prescription_audit;
CREATE POLICY clinical_audit_scope ON public.prescription_audit AS RESTRICTIVE FOR SELECT TO authenticated USING(patient_id=auth.uid() OR public.can_access_patient(patient_id));
CREATE OR REPLACE FUNCTION public.guard_prescription_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF auth.role()='service_role' THEN RETURN NEW; END IF; IF NOT public.can_access_patient(NEW.patient_id) OR NEW.doctor_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Clinical access required'; END IF; IF NEW.appointment_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.appointments a WHERE a.id=NEW.appointment_id AND a.patient_id=NEW.patient_id) THEN RAISE EXCEPTION 'Invalid prescription appointment'; END IF; IF TG_OP='UPDATE' AND (NEW.patient_id IS DISTINCT FROM OLD.patient_id OR NEW.appointment_id IS DISTINCT FROM OLD.appointment_id) THEN RAISE EXCEPTION 'Protected prescription ownership'; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.guard_prescription_write() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE TRIGGER prescription_security BEFORE INSERT OR UPDATE ON public.prescriptions FOR EACH ROW EXECUTE FUNCTION public.guard_prescription_write();
DROP POLICY IF EXISTS assignment_read ON public.clinical_assignments;
CREATE POLICY assignment_read ON public.clinical_assignments FOR SELECT TO authenticated USING(doctor_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS assignment_admin_insert ON public.clinical_assignments;
CREATE POLICY assignment_admin_insert ON public.clinical_assignments FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND assigned_by=auth.uid() AND public.has_role(doctor_id,'doctor'));
DROP POLICY IF EXISTS assignment_admin_delete ON public.clinical_assignments;
CREATE POLICY assignment_admin_delete ON public.clinical_assignments FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.guard_deletion_pending() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE owner_id uuid; BEGIN IF TG_TABLE_NAME IN ('appointments','case_records','prescriptions') THEN owner_id:=NEW.patient_id; ELSIF TG_TABLE_NAME='profiles' THEN owner_id:=NEW.id; ELSE owner_id:=NEW.user_id; END IF; IF EXISTS(SELECT 1 FROM public.account_deletion_requests WHERE user_id=owner_id AND processing_state IN ('processing','failed','completed') AND (scope='account' OR processing_state<>'completed')) THEN IF TG_TABLE_NAME='profiles' AND auth.role()='service_role' AND TG_OP='UPDATE' AND NEW.full_name='' AND NEW.phone IS NULL AND NEW.date_of_birth IS NULL AND NEW.gender IS NULL AND NEW.city IS NULL AND NEW.avatar_url IS NULL THEN RETURN NEW; END IF; RAISE EXCEPTION 'Account privacy processing in progress'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER deletion_hold BEFORE INSERT OR UPDATE ON public.payments FOR EACH ROW EXECUTE FUNCTION public.guard_deletion_pending();
CREATE TRIGGER deletion_hold BEFORE INSERT OR UPDATE ON public.prescriptions FOR EACH ROW EXECUTE FUNCTION public.guard_deletion_pending();
CREATE POLICY report_deletion_read_hold ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING(bucket_id<>'patient-reports' OR NOT EXISTS(SELECT 1 FROM public.account_deletion_requests WHERE user_id=auth.uid() AND processing_state IN ('processing','failed','completed') AND (scope='account' OR processing_state<>'completed')));
DO $$ DECLARE t text; col text; BEGIN FOR t,col IN SELECT * FROM (VALUES('appointments','patient_id'),('case_records','patient_id'),('prescriptions','patient_id'),('prescription_audit','patient_id'),('orders','user_id'),('payments','user_id'),('profiles','id'),('health_consent_receipts','user_id'),('user_roles','user_id')) v(t,col) LOOP EXECUTE format('CREATE POLICY deletion_identity_hold ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (NOT EXISTS(SELECT 1 FROM public.account_deletion_requests r WHERE r.user_id=auth.uid() AND r.processing_state IN (''processing'',''failed'',''completed'') AND (r.scope=''account'' OR r.processing_state<>''completed''))) WITH CHECK (NOT EXISTS(SELECT 1 FROM public.account_deletion_requests r WHERE r.user_id=auth.uid() AND r.processing_state IN (''processing'',''failed'',''completed'') AND (r.scope=''account'' OR r.processing_state<>''completed'')))',t); END LOOP; END $$;